WITH with_last AS (SELECT s.*, latest.subscription_status FROM customers s JOIN LATERAL (SELECT c.status AS subscription_status FROM subscriptions c WHERE c.customer_id = s.id ORDER BY c.end_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT country, PERCENTILE_APPROX(age, 0.9) AS age_p90, COUNT(DISTINCT city) AS distinct_cities, COUNT(*) FILTER (WHERE subscription_status = 'PAUSED') AS paused_rows FROM with_last GROUP BY country ORDER BY distinct_cities DESC NULLS FIRST
